boolean existsInducingPathInto(Node x, Node y, Graph graph) {
    if (x.getNodeType()!= NodeType.MEASURED) throw new IllegalArgumentException();
    if (y.getNodeType()!= NodeType.MEASURED) throw new IllegalArgumentException();
    Set<Node> induced = new HashSet<>();
    for (Node b : graph.getAdjacentNodes(x)) {
        collectInducedNodesVisit(graph, x, b, induced);
    }
    return induced.contains(y);
}

private static void collectInducedNodesVisit(Graph graph, Node x, Node b, Set<Node> induced) {
    if (induced.contains(b)) {
        return;
    }
    induced.add(b);
    for (Node c : graph.getAdjacentNodes(b)) {
        collectInducedNodesVisit(graph, x, c, induced);
    }
}

